INSERT INTO `apex_apex_chatbot_logs` VALUES (1,'sid_ktdihtete',0,'Bugün hangi basketbol ve voleybol salonları boş, hakem ücreti nedir?','🏀🏐 **APEX ARENA Salon Kiralama & Canlı Müsaitlik (Bugün (23.11.2026)):**\n• **Arena Basketbol 1 (FIBA Parke)** — ₺1.850/saat *(+Lisanslı Hakem: ₺450)*\n  ↳ Öne çıkan boş saatler: `10:00, 14:00, 18:00, 20:00`\n• **Arena Basketbol 2 (Performans)** — ₺1.550/saat *(+Lisanslı Hakem: ₺450)*\n  ↳ Öne çıkan boş saatler: `10:00, 14:00, 18:00, 19:00`\n• **Arena Voleybol Pro (CEV Taraflex)** — ₺1.450/saat *(+Lisanslı Hakem: ₺450)*\n  ↳ Öne çıkan boş saatler: `10:00, 14:00, 18:00, 19:00`\n\n⚖️ **Hakem Ayarlama Hizmeti:** Rezervasyon formunda tek tıkla TBF/TVF lisanslı hakem ekleyebilirsin!','local-hybrid','2026-11-23 22:21:26'),(2,'sid_ktdihtete',0,'180 cm 82 kg analiz et','📊 **Anlık VKİ Analizin (180 cm / 82 kg):**\nVücut Kitle İndeksin: **25.3** (*Hafif Kilolu*)\n\n🎯 **APEX AI Önerisi:** Yağ yakımı ve metabolizma hızlandırma için **Elif Karaca** ile Grupsal HIIT + **Selin Yılmaz** ile 8 Seans Fonksiyonel PT paketini öneriyorum.','local-hybrid','2026-11-23 22:21:31'),(3,'sid_xqf3jpcua',0,'merhaba','👋 Merhaba! Ben **APEX AI Spor Koçu**.\nSana şu konularda canlı tesis verileriyle anında yardımcı olabilirim:\n• 🏀 **Basketbol (2 adet) & Voleybol (1 adet)** salon kiralama ve **hakem hizmeti**\n• 🏋️ **Bireysel / Grupsal PT paketleri**, seans ücretleri ve antrenör seçimi\n• 📊 **VKİ analizi** (ör. `180 cm 82 kg` yazman yeterli!)\n• 💳 **Üyelik paketleri**, tesis olanakları (duş, otopark, kafe) ve canlı yoğunluk\n\nHangi konuda yardımcı olayım?','local-hybrid','2026-11-23 22:37:53'),(4,'sid_xqf3jpcua',0,'aylık ücretler ne kadar','🏋️ **PT Paketleri, Seans Ücretleri ve Eğitim Günleri:**\n• **Başlangıç 4 Seans Bireysel PT** (Bireysel · 4 Seans): **₺4.200** *(Seans başı ₺1.050)*\n  ↳ Günler: Haftada 1–2 Gün (Esnek Saat: 08:00–22:00)\n• **Dönüşüm 12 Seans Bireysel PT** (Bireysel · 12 Seans): **₺11.400** *(Seans başı ₺950)*\n  ↳ Günler: Haftada 3 Gün (Pzt/Çar/Cum veya Sal/Per/Cmt)\n• **Pro Atlet 24 Seans VIP PT** (Bireysel · 24 Seans): **₺20.400** *(Seans başı ₺850)*\n  ↳ Günler: Haftada 3–4 Gün (Öncelikli VIP Takvim)\n• **HIIT &amp; Yağ Yakımı Grup (8 Seans)** (Grupsal · 8 Seans): **₺2.800** *(Seans başı ₺350)*\n  ↳ Günler: Pazartesi & Çarşamba 18:30 · Cumartesi 08:30\n• **Reformer Pilates Butik Grup (8 Seans)** (Grupsal · 8 Seans): **₺3.600** *(Seans başı ₺450)*\n  ↳ Günler: Salı & Perşembe 08:30 / 20:00 · Cumartesi 12:00\n• **Basketbol &amp; Voleybol Kondisyon (12 Seans)** (Grupsal · 12 Seans): **₺4.200** *(Seans başı ₺350)*\n  ↳ Günler: Salı & Perşembe 18:30 · Cuma 18:30\n\n💡 İpucu: Boy ve kilonu yazarsan (örn. `178 cm 80 kg`) sana özel VKİ analizi ve PT programı önerebilirim!','local-hybrid','2026-11-23 22:38:03'),(5,'sid_wkx8copp6',2,'selamlar bana bir python kodu yaz','👋 Merhaba! Ben **APEX AI Spor Koçu**.\nSana şu konularda canlı tesis verileriyle anında yardımcı olabilirim:\n• 🏀 **Basketbol (2 adet) & Voleybol (1 adet)** salon kiralama ve **hakem hizmeti**\n• 🏋️ **Bireysel / Grupsal PT paketleri**, seans ücretleri ve antrenör seçimi\n• 📊 **VKİ analizi** (ör. `180 cm 82 kg` yazman yeterli!)\n• 💳 **Üyelik paketleri**, tesis olanakları (duş, otopark, kafe) ve canlı yoğunluk\n\nHangi konuda yardımcı olayım?','local-hybrid','2026-11-23 23:35:31'),(6,'sid_wkx8copp6',2,'ölüm','👋 Merhaba! Ben **APEX AI Spor Koçu**.\nSana şu konularda canlı tesis verileriyle anında yardımcı olabilirim:\n• 🏀 **Basketbol (2 adet) & Voleybol (1 adet)** salon kiralama ve **hakem hizmeti**\n• 🏋️ **Bireysel / Grupsal PT paketleri**, seans ücretleri ve antrenör seçimi\n• 📊 **VKİ analizi** (ör. `180 cm 82 kg` yazman yeterli!)\n• 💳 **Üyelik paketleri**, tesis olanakları (duş, otopark, kafe) ve canlı yoğunluk\n\nHangi konuda yardımcı olayım?','local-hybrid','2026-11-23 23:35:42'),(7,'sid_wkx8copp6',2,'canım cok sıkıldı','👋 Merhaba! Ben **APEX AI Spor Koçu**.\nSana şu konularda canlı tesis verileriyle anında yardımcı olabilirim:\n• 🏀 **Basketbol (2 adet) & Voleybol (1 adet)** salon kiralama ve **hakem hizmeti**\n• 🏋️ **Bireysel / Grupsal PT paketleri**, seans ücretleri ve antrenör seçimi\n• 📊 **VKİ analizi** (ör. `180 cm 82 kg` yazman yeterli!)\n• 💳 **Üyelik paketleri**, tesis olanakları (duş, otopark, kafe) ve canlı yoğunluk\n\nHangi konuda yardımcı olayım?','local-hybrid','2026-11-23 23:35:50'),(8,'sid_ktdihtete',2,'Bugün hangi basketbol ve voleybol salonları boş, hakem ücreti nedir?','🏀🏐 **APEX ARENA Salon Kiralama & Canlı Müsaitlik (Bugün (23.11.2026)):**\n• **Arena Basketbol 1 (FIBA Parke)** — ₺1.850/saat *(+Lisanslı Hakem: ₺450)*\n  ↳ Öne çıkan boş saatler: `10:00, 14:00, 18:00, 20:00`\n• **Arena Basketbol 2 (Performans)** — ₺1.550/saat *(+Lisanslı Hakem: ₺450)*\n  ↳ Öne çıkan boş saatler: `10:00, 14:00, 18:00, 19:00`\n• **Arena Voleybol Pro (CEV Taraflex)** — ₺1.450/saat *(+Lisanslı Hakem: ₺450)*\n  ↳ Öne çıkan boş saatler: `10:00, 14:00, 18:00, 19:00`\n\n⚖️ **Hakem Ayarlama Hizmeti:** Rezervasyon formunda tek tıkla TBF/TVF lisanslı hakem ekleyebilirsin!','local-hybrid','2026-11-23 23:50:53'),(9,'test_live_1',0,'canım çok sıkıldı','Of ya, anlıyorum seni. Bazen öyle boşluk hissi çöker insanın üzerine, değil mi? Ne oldu, bir şeye mi canın sıkıldı özel olarak, yoksa genel bir ruh hali mi bu? Belki biraz sohbet etmek iyi gelir. Ben Apex AI Koç olarak buradayım, seni dinlemeye hazırım.','gemini-live','2026-11-23 23:54:36'),(10,'test_live_1',0,'haklısın ya biraz basket atsam iyi gelir, bugün boş basketbol sahası var mı ve hakem çağırabiliyor muyuz?','Harika bir fikir! Basketbol her zaman iyi gelir ruha da bedene de. Hemen bir bakayım bugünkü boş saatlere ve hakem durumuna...\n\nEvet, bugün Arena Basketbol 1\'de (FIBA Parke) ve Arena Basketbol 2\'de (Standart) boş saatlerimiz var.\n\n*   **Arena Basketbol 1 (FIBA Parke):** 09:00, 10:00, 11:00, 14:00, 18:00 saatleri boş. Saatlik ücreti ₺1.850.\n*   **Arena Basketbol 2 (Performans):** 09:00, 10:00, 11:00, 14:00, 16:00 saatleri boş. Saatlik ücreti ₺1.550.\n\nHakem hizmeti de elbette sağlıyoruz! Hangi sahayı seçersen seç, hakem için saatlik ₺450 ek ücret oluyor.\n\nHangisi sana daha uygun olur? Belki bir arkadaşını da çağırıp maç yaparsınız, süper olur!','gemini-live','2026-11-23 23:54:38'),(11,'sid_ktdihtete',2,'canım cok sıkıldı','Of, anladım seni. Bazen öyle anlar olur ki, insanın içi daralır. Neden böyle hissediyorsun peki, anlatmak ister misin? Belki konuşmak iyi gelir. Ya da istersen bambaşka bir şeylerden de bahsedebiliriz, ne dersin?','gemini-live','2026-11-23 23:55:34'),(12,'sid_wkx8copp6',2,'selam','Selam! Nasılsın, nasıl gidiyor bugün? Ben Apex AI Koç, Apex Arena\'nın canlı yapay zeka asistanıyım. Sana nasıl yardımcı olabilirim? :)','gemini-live','2026-11-24 00:08:54'),(13,'sid_wkx8copp6',2,'naber','İyiyim, teşekkür ederim sorduğun için! Enerjim yüksek ve her zamanki gibi sporla iç içeyim. Peki sen neler yapıyorsun, keyifler nasıl? Belki biraz sohbet ederiz, ya da Apex Arena\'daki imkanlarımızdan bahsederim, ne dersin? :)','gemini-live','2026-11-24 00:08:58'),(14,'sid_xg29jk0bp',2,'naber bana bir pi sayısı soyle','Merhaba! Ben Apex AI Koç, nasılsın?\n\nPi sayısı mı? Tabii ki, 3.14159... Sonsuza giden bir sayı olduğu için tamamını söylemem mümkün değil ama bu başlangıç işini görür mü? :)','gemini-live','2026-11-24 23:40:23'),(15,'sid_xg29jk0bp',2,'gormez hepsini soyle','Ah, keşke söyleyebilsem! Pi sayısı matematikte sonsuz sayıda ondalık basamağa sahip, yani sonu olmayan bir sayı. Bu yüzden ne ben ne de başka biri onun tüm basamaklarını söyleyebilir. Çok gizemli, değil mi? :)\n\nAma istersen sana pi sayısının tarihindeki ilginç bir hikayeyi anlatabilirim, ne dersin? Ya da belki başka bir konuda sohbet edebiliriz?','gemini-live','2026-11-24 23:40:35'),(16,'sid_xg29jk0bp',2,'bana basit bir python kodu yaz','Harika bir fikir! Python basit ama çok güçlü bir dil. Ne tür bir kod yazmak istersin? Mesela adını soran ve sana \"Merhaba [Adın]!\" diyen küçük bir program yapabiliriz, ya da iki sayıyı toplayan bir şey...\n\nSenin için ne yazmamı istersin? 😊','gemini-live','2026-11-24 23:40:57'),(17,'sid_xg29jk0bp',2,'olur','Süper! O zaman sana adını soran ve seni selamlayan basit bir Python kodu yazayım:\n\n```python\n# Kullanıcının adını soruyoruz\nisim = input(\"Adınız nedir? \")\n\n# Kullanıcıya özel bir mesajla merhaba diyoruz\nprint(\"Merhaba, \" + isim + \"! Apex Arena\'ya hoş geldin!\")\n```\n\nBu kodu bir Python derleyicisinde çalıştırdığında, sana \"Adınız nedir?\" diye soracak, sen adını yazıp Enter\'a bastığında da sana özel olarak \"Merhaba, [Adın]! Apex Arena\'ya hoş geldin!\" diyecek. Çok basit ama başlangıç için harika, değil mi? 😊\n\nBaşka bir konuda kod yazmamı ister misin yoksa sporla ilgili bir şeyler mi konuşalım?','gemini-live','2026-11-24 23:41:05');
