INSERT INTO `apex_apex_coach_messages` VALUES (1,1,3,'coach','Kerem Alkan','Merhaba! Bu haftaki InBody ölçümünde kas kütlen +0.6 kg artmış, tebrikler. Yeni 7 günlük beslenme takvimini güncelledim, antrenman sonrası protein shake saatine dikkat edelim.',1,'2026-11-25 00:45:37'),(2,1,3,'student','Ahmet Yılmaz','Teşekkürler hocam! Yeni beslenme planını panelden gördüm, Perşembe 19:00 seansına kadar birebir uygulayacağım.',0,'2026-11-25 00:45:37'),(3,1,3,'student','Ahmet Yılmaz','Hocam bu hafta squat hedefime ulastim!',0,'2026-11-25 00:56:14'),(4,1,3,'coach','Kerem Alkan (Yönetim)','Harikasin Ahmet, bu ivmeyi koru!',0,'2026-11-25 00:57:39');
