INSERT INTO `apex_apex_coach_students` VALUES (1,3,'Kerem Alkan',2,'Ahmet Yılmaz','ahmet.yilmaz@example.com','Kas Kütlesi & Atletik Kuvvet','hedefte',88,'up',91,78.4,76.0,12,11,'Bench press ve squat kuvvetinde harika ivme yakaladın! Bu hafta antrenman sonrası 35g protein + kompleks karbonhidrat alımını aksatma ve Çarşamba günü 15 dk mobilite ekle.','2026-11-25 01:00:32'),(2,3,'Kerem Alkan',0,'Caner Öztürk','caner.ozturk@example.com','Basketbol Dikey Sıçrama','hedefte',78,'up',85,84.0,82.0,12,9,'Pliometrik kutu sıçrama serilerinde iniş kontrolün belirgin gelişti. Maç günlerinden önce bacak hacmini %20 hafifletelim.','2026-11-25 00:45:37'),(3,3,'Kerem Alkan',0,'Zeynep Kaya','zeynep.kaya@example.com','Yağ Yakımı & Sıkılaşma','dikkat',54,'down',62,66.5,60.0,12,6,'Son 10 günde akşam karbonhidratı ve uyku düzeni biraz sarkmış. Günlük su hedefini 2.8L seviyesine sabitleyip bu hafta 2 ek kardiyo seansı planlayalım.','2026-11-25 00:45:37'),(4,3,'Kerem Alkan',0,'Burak Aydın','burak.aydin@example.com','Omuz Rehabilitasyon & Postür','yeni',38,'up',79,81.2,79.0,8,3,'Rotator cuff ısınmalarını her antrenmandan önce bant ile 8 dakika uyguluyoruz. Ağrısız hareket açıklığı %90 seviyesine ulaştı.','2026-11-25 00:45:37'),(5,3,'Kerem Alkan',0,'Emre Şahin','emre.sahin@example.com','Hipertrofi & 10K Kondisyon','riskli',28,'down',45,92.4,85.0,12,3,'Son 2 haftadır randevu katılımın düştü. İş yoğunluğuna göre seans saatlerini 07:30 sabah dilimine çekip daha sürdürülebilir bir tempo kuralım.','2026-11-25 00:45:37'),(6,4,'Elif Karaca',0,'Selin Arslan','selin.arslan@example.com','HIIT & Metabolik Yağ Yakımı','hedefte',92,'up',95,59.8,58.0,16,14,'Nabız toparlanma süren muhteşem! Hedef kiloya 1.8 kg kaldı, protein alımını koruyarak yüksek yoğunluklu interval bloklarını sürdürüyoruz.','2026-11-25 00:45:37'),(7,4,'Elif Karaca',0,'Deniz Yıldız','deniz.yildiz@example.com','Maraton Dayanıklılık','dikkat',61,'up',70,71.0,69.0,12,7,'Uzun koşular öncesi elektrolit ve kompleks karbonhidrat yüklemesini 2 saat önceye çekelim.','2026-11-25 00:45:37');
