INSERT INTO `apex_apex_reviews` VALUES (1,'Mertcan Kılıç','APEX ELITE + PT',5,'FIBA parkeli basketbol salonu ve lisanslı hakem hizmeti kurumsal maçlarımız için kusursuz. Kapalı otopark ve EV şarj istasyonu büyük konfor.','published','2026-11-25 00:45:37'),(2,'Ece Demirtaş','APEX PRO',5,'Selin Hoca ile Reformer Pilates seansları duruşumu tamamen değiştirdi. Soyunma odaları ve Fin saunası gerçekten otel standartlarında.','published','2026-11-25 00:45:37'),(3,'Kaan Yıldırım','APEX ELITE + PT',5,'Koçum Kerem Alkan panelden haftalık beslenme takvimimi güncelleyip birebir mesajla takip ediyor. 2 ayda 6 kg yağ verip kas kütlemi artırdım.','published','2026-11-25 00:45:37'),(4,'Dilara Şen','APEX PRO',5,'Antrenman bitmeden Protein Kafe’den fit bowl ve whey shake ön siparişi veriyorum, duştan çıkınca hazır bekliyor. Makroların yazması harika.','published','2026-11-25 00:45:37'),(5,'Onur Aksoy','APEX CLASSIC',4,'Dijital QR kartla turnikeden ve otoparktan saniyeler içinde geçmek çok pratik. Akşam 19:00 yoğunluğunu grafikten kontrol edip sakin saatte geliyorum.','published','2026-11-25 00:45:37'),(6,'Ahmet Kaya','APEX PRO',5,'Yeni kat plani ve koc beslenme takibi muhtesem olmus!','published','2026-11-25 00:55:01');
/*!40000 ALTER TABLE `apex_apex_reviews` ENABLE KEYS */;
UNLOCK TABLES;

